import { generateDrizzleJson, generateMigration } from "drizzle-kit/api";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import * as schema from "./schema";

/**
 * Supabase runs the SQL files in ./drizzle (generated by `pnpm --filter @brokely/api
 * db:generate`), not schema.ts. This test keeps the two in step.
 */
const dir = join(import.meta.dirname, "..", "..", "drizzle");

describe("server migrations", () => {
  it("are up to date with schema.ts (run db:generate after changing the schema)", async () => {
    const snapshots = readdirSync(join(dir, "meta")).filter((f) => f.endsWith("_snapshot.json"));
    const latest = JSON.parse(readFileSync(join(dir, "meta", snapshots.sort().at(-1)!), "utf8"));

    const pending = await generateMigration(latest, generateDrizzleJson(schema, latest.id));

    expect(pending).toEqual([]);
  });
});
